WITH cleaned AS (SELECT id, customer_id, account_type, opened_date, status, DATE_ADD(opened_date, 39) AS opened_date_plus_39d FROM accounts WHERE opened_date >= DATE '2023-07-04' AND status IS NOT NULL) SELECT id, opened_date, opened_date_plus_39d, ROW_NUMBER() OVER w_recent AS row_seq, ROW_NUMBER() OVER (PARTITION BY MONTH(opened_date), status ORDER BY opened_date_plus_39d DESC, id) AS event_seq, ROW_NUMBER() OVER (PARTITION BY account_type ORDER BY opened_date, id) AS row_seq_2 FROM cleaned WINDOW w_recent AS (ORDER BY opened_date_plus_39d, id);
